package com.auralink.assistant;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import java.nio.file.*;
import java.nio.file.attribute.PosixFilePermissions;
import java.time.*;
import java.util.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import static com.auralink.assistant.AssistantExecutionRecords.*;

class AssistantGenerationControlTest {
 @TempDir Path directory;
 Path root,marker;
 @BeforeEach void setup()throws Exception{root=Files.createDirectory(directory.resolve("owned"),PosixFilePermissions.asFileAttribute(PosixFilePermissions.fromString("rwx------")));marker=root.resolve(AssistantGenerationControl.NAME);}
 void suspend()throws Exception{Files.writeString(marker,AssistantGenerationControl.CONTENT,StandardOpenOption.CREATE_NEW);Files.setPosixFilePermissions(marker,PosixFilePermissions.fromString("rw-------"));}
 @Test void durableSuspendRestartAndExplicitResume()throws Exception{var control=new AssistantGenerationControl(root);assertEquals("AVAILABLE",control.state());suspend();assertEquals("ASSISTANT_GENERATION_SUSPENDED",control.state());assertEquals(control.state(),new AssistantGenerationControl(root).state());Files.delete(marker);assertEquals("AVAILABLE",control.state());}
 @Test void unsafeContentPermissionsAndLinksFailClosed()throws Exception{var control=new AssistantGenerationControl(root);suspend();Files.writeString(marker,"wrong");assertEquals("ASSISTANT_GENERATION_CONTROL_UNAVAILABLE",control.state());Files.writeString(marker,AssistantGenerationControl.CONTENT);Files.setPosixFilePermissions(marker,PosixFilePermissions.fromString("rw-r--r--"));assertEquals("ASSISTANT_GENERATION_CONTROL_UNAVAILABLE",control.state());Files.delete(marker);Path outside=directory.resolve("outside");Files.writeString(outside,AssistantGenerationControl.CONTENT);Files.createSymbolicLink(marker,outside);assertEquals("ASSISTANT_GENERATION_CONTROL_UNAVAILABLE",control.state());assertEquals(AssistantGenerationControl.CONTENT,Files.readString(outside));}
 @Test void rootReplacementAndHardlinksRefuse()throws Exception{var control=new AssistantGenerationControl(root);suspend();Files.createLink(directory.resolve("copy"),marker);assertEquals("ASSISTANT_GENERATION_CONTROL_UNAVAILABLE",control.state());Files.delete(directory.resolve("copy"));Files.move(root,directory.resolve("old"));Files.createDirectory(root,PosixFilePermissions.asFileAttribute(PosixFilePermissions.fromString("rwx------")));assertEquals("ASSISTANT_GENERATION_CONTROL_UNAVAILABLE",control.state());}
 AssistantExecutionService service(AssistantExecutionStore store,AssistantStore foundation,AssistantAiClient ai,AssistantGenerationControl control){return new AssistantExecutionService(store,foundation,mock(AssistantAttachmentService.class),ai,null,null,new AssistantExecutionProperties(),new ObjectMapper(),Clock.systemUTC(),control::state);}
 AssistantExecutionService.Command command(UUID branch){return new AssistantExecutionService.Command(branch,0,"new-request-key","question",List.of(),"text",Map.of(),List.of());}
 @Test void newAdmissionRefusedButOriginalReplayAndReadsRemain()throws Exception{var store=mock(AssistantExecutionStore.class);var foundation=mock(AssistantStore.class);var ai=mock(AssistantAiClient.class);suspend();try(var service=service(store,foundation,ai,new AssistantGenerationControl(root))){UUID session=UUID.randomUUID(),branch=UUID.randomUUID();var failure=assertThrows(AssistantFailure.class,()->service.admit(1,session,command(branch)));assertEquals("ASSISTANT_GENERATION_SUSPENDED",failure.code());verify(store,never()).admit(anyLong(),any());verifyNoInteractions(ai);var existing=new Accepted(null,true);when(store.replayAdmission(eq(1L),any())).thenReturn(Optional.of(existing));assertSame(existing,service.admit(1,session,command(branch)));assertSame(store,service.store());}}
 @Test void queuedClaimsPauseAndResumeWithoutChangingPendingRecords()throws Exception{var store=mock(AssistantExecutionStore.class);var foundation=mock(AssistantStore.class);var ai=mock(AssistantAiClient.class);UUID session=UUID.randomUUID();when(store.pendingSessions(50)).thenReturn(List.of(new Pending(1,session)));when(store.claim(eq(1L),eq(session),anyString(),any())).thenReturn(Optional.empty());suspend();try(var service=service(store,foundation,ai,new AssistantGenerationControl(root))){service.tick();verify(store,never()).pendingSessions(anyInt());verify(store,never()).claim(anyLong(),any(),anyString(),any());Files.delete(marker);service.tick();verify(store).claim(eq(1L),eq(session),anyString(),any());verify(store,times(2)).recoverExpired(50);verifyNoInteractions(ai);}}
 @Test void alreadyClaimedWorkCannotDispatchThroughSuspension()throws Exception{var store=mock(AssistantExecutionStore.class);var foundation=mock(AssistantStore.class);var ai=mock(AssistantAiClient.class);UUID id=UUID.randomUUID();Run run=new Run(id,UUID.randomUUID(),UUID.randomUUID(),"CHAT","EXECUTING",UUID.randomUUID(),1,1,"","text",Map.of(),"fixture",Instant.now().plusSeconds(30),null,null,null,1,Map.of(),Map.of(),Map.of(),null,Instant.now(),Instant.now());when(store.get(1,id)).thenReturn(run);suspend();try(var service=service(store,foundation,ai,new AssistantGenerationControl(root))){var execute=AssistantExecutionService.class.getDeclaredMethod("execute",long.class,Run.class);execute.setAccessible(true);execute.invoke(service,1L,run);verify(store,never()).markIntent(anyLong(),any(),anyLong(),anyString(),anyString());verify(ai,never()).execute(any(),any(),any());verify(store).complete(eq(1L),eq(id),eq(1L),anyString(),eq("FAILED"),eq(""),anyList(),anyMap(),anyList(),eq("ASSISTANT_GENERATION_SUSPENDED"));}}
}
